"""
@package mocaxpy.MocaxSliding
Mocax sliding functions module.

Exports the Mocax sliding function class.
"""

import ctypes
import mocaxpy.MocaxCInterface
from mocaxpy.MocaxException import *
from mocaxpy.MocaxDomain import *
from mocaxpy.MocaxNs import *
import copy
import sys
import os

if sys.version_info.major >= 3:
    xrange = range


class MocaxSliding(object):
    """
    The Mocax sliding function class.

    The definition of Mocax sliding functions.
    """

    def __init__(self, original, num_dimensions_per_partial, domain, n, reference_point,
                 special_points=None, additional_data=None):
        """
        Mocax constructor.

        Builds a Mocax sliding function object, taking a callable function, the number of partials and their dimensionalities, a domain,
        the accuracy parameters and/or an error threshold, a reference point, and other optional parameters.
        @param[in] original The original, callable function. If a @c None function and only @c n are passed, construction will be incomplete and must be finished with get_evaluation_points() and set_original_function_values().
                   Allowed types: Callables, @c None
        @param[in] num_dimensions_per_partial The number of dimensions for each partial function. A container with each element being an integer number in the range [1,58].
                   Allowed types: @c tuple, @c list
        @param[in] domain A MocaxDomain object with the domain of the function to construct.
                   Allowed types: @ref mocaxpy.MocaxDomain.MocaxDomain
        @param[in] n A MocaxNs object with the accuracy parameter(s) of each dimension.
                   Allowed types: mocaxpy.MocaxNs.MocaxNs
        @param[in] reference_point A container with the coordinates of the reference point.
                   Allowed types: @c tuple, @c list
        @param[in] special_points An optional MocaxSpecialPoints object with a set of special points.
                   Allowed types: mocaxpy.MocaxSpecialPoints.MocaxSpecialPoints, @c None
        @param[in] additional_data An optional parameter with optional data that will be forwarded to
                   the original function during the construction.
                   Allowed types: @c c_void_p, @c None
        """

        self.__init()

        # Arguments validation
        if num_dimensions_per_partial is None:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_NULL_ARGUMENT, "A set of dimensionalities for the partial functions is required")
        if domain is None:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_NULL_ARGUMENT, "A domain is required")
        if original is not None and not callable(original):
            raise TypeError("original must be a callable argument")
        if not isinstance(num_dimensions_per_partial, (list, tuple)):
            raise TypeError("num_dimensions_per_partial has to be a list or a tuple")
        if not isinstance(domain, MocaxDomain):
            raise TypeError("domain must be a MocaxDomain. " + type(domain).__name__ + " received instead")
        if n is None:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_NULL_ARGUMENT, "An N has to be provided")
        if not isinstance(n, MocaxNs):
            raise TypeError("n must be a MocaxNs. " + type(n).__name__ + " received instead")
        if not isinstance(reference_point, (list, tuple)):
            raise TypeError("reference_point has to be a list or a tuple")
        if len(reference_point) != sum(num_dimensions_per_partial):
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_MISMATCH, "The dimensionality of the reference point must match the aggregated dimensionality of the function. len(reference_point) = " +
                                 str(len(reference_point)))
        if special_points is not None:
            if not isinstance(special_points, MocaxSpecialPoints):
                raise TypeError("When provided, specialPoints must be a MocaxSpecialPoints. " +
                                 type(special_points).__name__ + " received instead")

        num_partials = len(num_dimensions_per_partial)
        num_dimensions = sum(num_dimensions_per_partial)

        # Construction
        original_function = mocaxpy.MocaxCInterface.MOCAX_ORIGINAL_FUNCTION()
        if original is not None:
            original_function.original_function_def = mocaxpy.MocaxCInterface.MOCAX_ORIGINAL_FUNCTION_DEF(original)
        else:
            original_function.original_function_def = mocaxpy.MocaxCInterface.MOCAX_ORIGINAL_FUNCTION_DEF(0)
        original_function.dimension = sum(num_dimensions_per_partial)
        original_function.to_dimension = 1
        original_function.to_defaultValues = ctypes.cast((ctypes.c_double * original_function.dimension)(),
                                                          ctypes.POINTER(ctypes.c_double))
        original_function.to_defaultIndexes = ctypes.cast((ctypes.c_int64 * original_function.to_dimension)(),
                                                           ctypes.POINTER(ctypes.c_int64))
        original_function.additional_data = additional_data

        domain_arr = domain.export_as_multidimensional_array()
        if special_points is None:
            # Without special points
            sizes_arr = (ctypes.c_int64 * n.get_num_dimensions())()
            for i in xrange(n.get_num_dimensions()):
                sizes_arr[i] = ctypes.c_int64(n.get_n(i, 0))
            result = mocaxpy.MocaxCInterface.mocax_sliding_generate_without_special_points(
                original_function,
                num_partials,
                (ctypes.c_int64 * len(num_dimensions_per_partial))(*num_dimensions_per_partial),
                domain_arr,
                sizes_arr,
                (ctypes.c_double * len(reference_point))(*reference_point),
                self.__mocax_sliding_function
                )
            if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
                raise MocaxException(result)
        else:
            # With special points
            n_copy = copy.deepcopy(n)
            n_copy.make_explicit(domain, special_points)
            sizes_arr = n_copy.export_as_multidimensional_array()
            special_points_arr = special_points.export_as_multidimensional_array()
            num_special_points = []
            for i in xrange(special_points.get_num_dimensions()):
                num_special_points.append(special_points.get_num_special_points_for_dimension(i))
            result = mocaxpy.MocaxCInterface.mocax_sliding_generate_with_special_points_explicit_ns(
                original_function,
                num_partials,
                (ctypes.c_int64 * len(num_dimensions_per_partial))(*num_dimensions_per_partial),
                domain_arr,
                sizes_arr,
                (ctypes.c_double * len(reference_point))(*reference_point),
                (ctypes.c_int64 * len(num_special_points))(*num_special_points),
                special_points_arr,
                self.__mocax_sliding_function
                )
            if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
                raise MocaxException(result)

    def __del__(self):
        """
        Mocax sliding function destructor.
        """

        result = mocaxpy.MocaxCInterface.mocax_sliding_destroy(self.__mocax_sliding_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            # Exceptions are ignored here, so we just write to stderr instead.
            sys.stderr.write("Error destroying the Mocax sliding function object (" + str(result) + ")")
        else:
            mocaxpy.MocaxCInterface.mocax_free(self.__mocax_sliding_function)

    def clone(self):
        """
        Cloning method.

        Creates a deep copy of the object. Note the built-in Python @c copy.deepcopy function will not work
        as the underlying copy has to be made inside of the native Mocax library as well.

        @return A new Mocax sliding function object identical to this one.
                Return type: mocaxpy.MocaxSliding.MocaxSliding
        """

        mocax_sliding_copy = mocaxpy.MocaxCInterface.mocax_sliding_allocate()
        result = mocaxpy.MocaxCInterface.mocax_sliding_clone(self.__mocax_sliding_function, mocax_sliding_copy)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        copy = MocaxSliding.__new__(MocaxSliding)  # Necessary to instantiate a new MocaxSliding
                                                   # (__new__) without calling its constructor/initializator (__init__)
        copy.__mocax_sliding_function = mocax_sliding_copy
        return copy

    def eval(self, point):
        """
        Evaluates the Mocax sliding function or its derivative at the point determined by (x_1, ..., x_i).

        @note For performance reasons, this method doesn't typecheck its arguments.

        @param[in] point Coordinates of the point to evaluate. A container of num_dimensions
                   decimal numbers in the range [x_i_min, x_i_max].
                   Allowed types: @c list, @c tuple
        """

        y = ctypes.c_double(0.0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_eval(self.__mocax_sliding_function, (ctypes.c_double * len(point))(*point), ctypes.pointer(y))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        return y.value

    def serialize(self, filename):
        """
        Serializes a Mocax sliding function object to a file.

        @param[in] filename The file name.
                   Allowed types: @c str
        """

        if not isinstance(filename, str):
            raise TypeError("filename expected to be a string. " + type(filename).__name__ + " received instead")

        output_buffer = ctypes.c_void_p()
        output_size = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_serialize(self.__mocax_sliding_function,
                                                                 ctypes.pointer(output_buffer),
                                                                 ctypes.pointer(output_size))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        data = ctypes.cast(output_buffer, ctypes.POINTER(ctypes.c_ubyte * output_size.value))
        byte_data = ''.join(map(chr, data.contents))
        with open(filename, "wb") as f:
            from sys import version_info
            if sys.version_info.major >= 3:
                f.write(bytes(data.contents))
            else:
                f.write(byte_data)

    def __getstate__(self):
        """
        Pickle's serialization mechanism.
        """
        output_buffer = ctypes.c_void_p()
        output_size = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_serialize(self.__mocax_sliding_function,
                                                                 ctypes.pointer(output_buffer),
                                                                 ctypes.pointer(output_size))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        data = ctypes.cast(output_buffer, ctypes.POINTER(ctypes.c_ubyte * output_size.value))
        if (sys.version_info.major >= 3):
            return bytes(data.contents)
        else:
            return ''.join(map(chr, data.contents))

    @staticmethod
    def deserialize(filename):
        """
        Deserializes a Mocax sliding function object from a file.

        @param[in] filename The file name.
                   Allowed types: @c str
        """

        if not isinstance(filename, str):
            raise TypeError("filename expected to be a string. " + type(filename).__name__ + " received instead")

        file_size = os.path.getsize(filename)
        with open(filename, "rb") as f:
            byte_data = f.read()
        input_buffer = ctypes.cast(byte_data, ctypes.POINTER(ctypes.c_ubyte))
        deserialized = MocaxSliding.__new__(MocaxSliding)  # Necessary to instantiate a new Mocax
                                                           # (__new__) without calling its constructor/initializator (__init__)
        deserialized.__mocax_sliding_function = mocaxpy.MocaxCInterface.mocax_sliding_allocate()
        result = mocaxpy.MocaxCInterface.mocax_sliding_deserialize(input_buffer, file_size, deserialized.__mocax_sliding_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        return deserialized

    def __setstate__(self, byte_data):
        """
        Pickle's deserialization mechanism.
        """
        input_buffer = ctypes.cast(byte_data, ctypes.POINTER(ctypes.c_ubyte))
        self.__mocax_sliding_function = mocaxpy.MocaxCInterface.mocax_sliding_allocate()
        result = mocaxpy.MocaxCInterface.mocax_sliding_deserialize(input_buffer, len(byte_data), self.__mocax_sliding_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        return self

    @staticmethod
    def get_object_serialization_version(filename):
        """
        Gets the version of an object serialization.

        @param[in] filename The file name.
                   Allowed types: @c str
        @return The version code. The version has the form @c MMmmr, where @c MM are two digits for the @e major version, @c mm two digits for the @e minor version, and @c r one digit for the @e revision.
                Return type: @c int
        """

        if not isinstance(filename, str):
            raise TypeError("filename expected to be a string. " + type(filename).__name__ + " received instead")

        file_size = os.path.getsize(filename)
        with open(filename, "rb") as f:
            byte_data = f.read()
        input_buffer = ctypes.cast(byte_data, ctypes.POINTER(ctypes.c_ubyte))
        version = ctypes.c_uint16(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_get_object_serialization_version(input_buffer, file_size, ctypes.pointer(version))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        return version.value

    def get_num_dimensions(self):
        """
        Gets the number of dimensions of the Mocax sliding function.

        @return The number of dimensions of this sliding function.
                Return type: @c int
        """

        num_dimensions = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_get_num_dimensions(self.__mocax_sliding_function,
                                                                          ctypes.pointer(num_dimensions))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        return num_dimensions.value

    def get_num_evaluation_points(self):
        """
        Gets the number of points to evaluate for this function.
        @return The number of points to evaluate.
                Return type: @c int
        """
        num_points = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_get_num_evaluation_points(self.__mocax_sliding_function, ctypes.pointer(num_points))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

        return num_points.value

    def get_evaluation_points(self):
        """
        Gets the points to be evaluated for the second step of a deferred construction (using MocaxSliding.set_original_function_values()).
        @return A list with the points to be evaluated (each point in the form of a list of coordinates of length MocaxSliding.get_num_dimensions()).
                Return type: @c list
        """
        num_points = ctypes.c_int64(0)
        points_arr = ctypes.POINTER(ctypes.c_double)()
        result = mocaxpy.MocaxCInterface.mocax_sliding_get_evaluation_points(self.__mocax_sliding_function, ctypes.pointer(num_points), ctypes.pointer(points_arr))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

        num_dimensions = self.get_num_dimensions()

        points = []
        for i in xrange(num_points.value):
            point = []
            for j in xrange(num_dimensions):
                point.append(points_arr[i * num_dimensions + j])
            points.append(point)
        return points

    def set_original_function_values(self, values):
        """
        Sets the evaluation of the points retrieved with MocaxSliding.get_evaluation_points() to complete the deferred construction.
        @param[in] values The evaluation of the points, in the same order as they were when retrieved.
                   Allowed types: @c list, @c tuple
        """

        # Validate inputs
        if not isinstance(values, (list, tuple)):
            raise TypeError()

        expected_num_points = self.get_num_evaluation_points()
        if len(values) != expected_num_points:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_SIZES_MISMATCH, "The number of expected values mismatch the number of received values. Expected: " + str(expected_num_points) + " != Received: " + str(len(values)))

        values_arr = (ctypes.c_double * len(values))(*values)
        result = mocaxpy.MocaxCInterface.mocax_sliding_set_original_function_values(self.__mocax_sliding_function, values_arr)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

    def is_construction_finished(self):
        """
        Gets whether the MoCaX sliding function object is completely constructed or not.
        @return @c True if the object is completely constructed, @c False if it's not.
                Return type: @c bool
        """
        finished = ctypes.c_uint8(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_is_construction_finished(self.__mocax_sliding_function, ctypes.pointer(finished))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        return True if finished != 0 else False

    def get_domain(self):
        """
        Gets the domain of the Mocax sliding function.

        @return The domain of the Mocax sliding function.
                Return type: mocaxpy.MocaxDomain.MocaxDomain
        """

        num_dimensions = self.get_num_dimensions()
        domain_arr = (ctypes.c_double * (num_dimensions * 2))()
        result = mocaxpy.MocaxCInterface.mocax_sliding_get_domain(self.__mocax_sliding_function,
                                                                  ctypes.cast(domain_arr, ctypes.POINTER(ctypes.c_double)))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        domain_list = []
        for i in xrange(num_dimensions):
            domain_list.append([domain_arr[i * 2], domain_arr[i * 2 + 1]])
        return MocaxDomain(domain_list)

    def get_special_points(self):
        """
        Gets the set of special points used to build this sliding function.

        @return The set of special points of the function.
                Return type: mocaxpy.MocaxSpecialPoints.MocaxSpecialPoints
        """
        num_dimensions = self.get_num_dimensions()
        n_special_points = ctypes.c_int64(0)
        v_special_points = ctypes.POINTER(ctypes.c_double)()
        special_points_list = []
        for i in xrange(num_dimensions):
            result = mocaxpy.MocaxCInterface.mocax_sliding_get_special_points_for_dimension(
                self.__mocax_sliding_function, i, ctypes.pointer(v_special_points), ctypes.pointer(n_special_points))
            if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
                raise MocaxException(result)
            special_points_list_entry = []
            for j in xrange(n_special_points.value):
                special_points_list_entry.append(v_special_points[j])
            special_points_list.append(special_points_list_entry)
        return MocaxSpecialPoints(special_points_list)

    def get_used_ns(self):
        """
        Gets the largest accuracy parameter N of each dimension used to build this sliding function.

        @return The largest accuracy parameter N of each dimension of the function.
                Return type: @c list
        """

        num_dimensions = self.get_num_dimensions()
        n_arr = (ctypes.c_int64 * num_dimensions)()
        result = mocaxpy.MocaxCInterface.mocax_sliding_get_used_ns(self.__mocax_sliding_function,
                                                                   ctypes.cast(n_arr, ctypes.POINTER(ctypes.c_int64)))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        n_list = []
        for i in xrange(num_dimensions):
            n_list.append(n_arr[i])
        return MocaxNs(n_list)

    def set_descriptor(self, descriptor):
        """
        Sets the function descriptor (a short string used to identify an individual object).

        @param[in] descriptor The descriptor string. Pass @c None to remove the descriptor.
        """

        try:
            if (descriptor is not None):
                if not isinstance(descriptor, (str)):
                    raise TypeError("descriptor must be a string or None.")
                if (sys.version_info.major >= 3):
                    descriptor_char_p = ctypes.c_char_p(descriptor.encode('utf-8'))
                else:
                    descriptor_char_p = ctypes.c_char_p(descriptor)
            else:
                descriptor_char_p = ctypes.c_char_p("")
        except Exception as e:
            raise e
        result = mocaxpy.MocaxCInterface.mocax_sliding_set_descriptor(self.__mocax_sliding_function,
                                                                      descriptor_char_p)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

    def get_descriptor(self):
        """
        Gets the function descriptor.

        @return The descriptor of this function.
                Return type: @c str
        """

        descriptor = ctypes.c_char_p()
        length = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_get_descriptor(self.__mocax_sliding_function,
                                                                      ctypes.pointer(descriptor),
                                                                      ctypes.pointer(length))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

        if (sys.version_info.major >= 3):
            out_descriptor = str(descriptor.value.decode())
        else:
            out_descriptor = str(descriptor.value)
        return out_descriptor;


    def __str__(self):
        """
        Gets a string representation/summary of this function.
        @return The function summary in string format.
                Return type: @c str
        """
        description = ctypes.c_char_p()
        length = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_sliding_function_to_string(self.__mocax_sliding_function,
                                                                          ctypes.pointer(description),
                                                                          ctypes.pointer(length))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

        if (sys.version_info.major >= 3):
            out_description = str(description.value.decode())
        else:
            out_description = str(description.value)
        return out_description

    def __iadd__(self, other):
        """
        Assignment with increment operator.

        "Increments" a Mocax sliding function object by adding another.
        @param[in] other The second Mocax sliding function object ("the increment") that will be added to this one. Allowed types: mocaxpy.MocaxSliding.MocaxSliding
        @return A reference to self.
                Return type: mocaxpy.MocaxSliding.MocaxSliding
        """

        if not isinstance(other, mocaxpy.MocaxSliding):
            raise NotImplementedError()
        new_mocax_sliding_function = mocaxpy.MocaxCInterface.mocax_sliding_allocate()
        result = mocaxpy.MocaxCInterface.mocax_sliding_add_functions(self.__mocax_sliding_function, other._MocaxSliding__mocax_sliding_function, new_mocax_sliding_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        mocaxpy.MocaxCInterface.mocax_sliding_destroy(self.__mocax_sliding_function)
        self.__mocax_sliding_function = new_mocax_sliding_function
        return self

    def __isub__(self, other):
        """
        Assignment with decrement operator.

        "Decrements" a Mocax sliding function object by subtracting another.
        @param[in] other The second Mocax sliding function object ("the decrement") that will be subtracted from this one. Allowed types: mocaxpy.MocaxSliding.MocaxSliding
        @return A reference to self.
                Return type: mocaxpy.MocaxSliding.MocaxSliding
        """

        if not isinstance(other, mocaxpy.MocaxSliding):
            raise NotImplementedError()
        new_mocax_sliding_function = mocaxpy.MocaxCInterface.mocax_sliding_allocate()
        result = mocaxpy.MocaxCInterface.mocax_sliding_subtract_functions(self.__mocax_sliding_function, other._MocaxSliding__mocax_sliding_function, new_mocax_sliding_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        mocaxpy.MocaxCInterface.mocax_sliding_destroy(self.__mocax_sliding_function)
        self.__mocax_sliding_function = new_mocax_sliding_function
        return self

    def __add__(self, other):
        """
        Addition operator.

        Adds two Mocax sliding function objects.
        @param[in] other A second Mocax sliding function object that will be added to this one. Allowed types: mocaxpy.MocaxSliding.MocaxSliding
        @return A new Mocax sliding function resulting from the addition of this Mocax sliding function and another.
                Return type: mocaxpy.MocaxSliding.MocaxSliding
        """

        if not isinstance(other, mocaxpy.MocaxSliding):
            raise NotImplementedError()
        out_mocax_sliding = self.clone()
        out_mocax_sliding += other
        return out_mocax_sliding

    def __sub__(self, other):
        """
        Subtraction operator.

        Subtracts two Mocax sliding function objects.
        @param[in] other A second Mocax sliding function object that will be subtracted from this one. Allowed types: mocaxpy.MocaxSliding.MocaxSliding
        @return A new Mocax sliding function resulting from the subtraction of a Mocax sliding function from this one.
                Return type: mocaxpy.MocaxSliding.MocaxSliding
        """

        if not isinstance(other, mocaxpy.MocaxSliding):
            raise NotImplementedError()
        out_mocax_sliding = self.clone()
        out_mocax_sliding -= other
        return out_mocax_sliding

    def __init(self):
        self.__mocax_sliding_function = mocaxpy.MocaxCInterface.mocax_sliding_allocate()
